insert into public.experiences (id, company, logo_path, position, type, start_date, end_date, responsibilities, learnings, impact, status, sort_order, deleted_at) values
  ('56b082da-5395-48da-a068-55ced6348e8c', 'Nusantara Digital Studio', null, '{"en":"Mobile Developer Intern","id":"Mobile Developer Intern"}'::jsonb, 'internship', '2026-07-01', null, '{"en":"Built and shipped Flutter features for a retail app used by thousands of customers.\nIntegrated REST APIs and Firebase push notifications.\nWorked with designers and backend engineers in two-week sprints.","id":"Membangun dan merilis fitur Flutter untuk aplikasi retail yang dipakai ribuan pelanggan.\nMengintegrasikan REST API dan push notification Firebase.\nBekerja bersama desainer dan backend engineer dalam sprint dua mingguan."}'::jsonb, '{"en":"Structuring a large Flutter codebase with clean architecture and GetX.\nWriting widget tests and reviewing pull requests in a team.","id":"Menyusun codebase Flutter besar dengan clean architecture dan GetX.\nMenulis widget test dan me-review pull request dalam tim."}'::jsonb, '{"en":"Cut the product list load time noticeably by refactoring state management and caching.\nShipped the checkout redesign that raised completed orders.","id":"Mempercepat waktu muat daftar produk secara signifikan lewat refactor state management dan caching.\nMerilis desain ulang checkout yang menaikkan jumlah pesanan selesai."}'::jsonb, 'published', null, null),
  ('fe31f74c-9a73-4f1c-a644-9886ff593e0e', 'Kode Kreatif', null, '{"en":"Web Developer Intern","id":"Web Developer Intern"}'::jsonb, 'internship', '2025-08-01', '2025-12-31', '{"en":"Developed an internal inventory dashboard with Laravel and Vue.\nWrote REST endpoints and database migrations for stock and sales data.","id":"Mengembangkan dashboard inventaris internal dengan Laravel dan Vue.\nMenulis endpoint REST dan migrasi database untuk data stok dan penjualan."}'::jsonb, '{"en":"Designing relational schemas and writing efficient queries.\nWorking with Git flow and code reviews in a professional team.","id":"Merancang skema relasional dan menulis query yang efisien.\nBekerja dengan Git flow dan code review dalam tim profesional."}'::jsonb, '{"en":"Replaced manual spreadsheets, saving the warehouse team hours every week.","id":"Menggantikan spreadsheet manual sehingga tim gudang menghemat berjam-jam setiap minggu."}'::jsonb, 'published', null, null),
  ('76d8d37a-9fb6-485b-aec0-2f447a6a0a4a', 'Earlier Company', null, '{"en":"Staff","id":"Staf"}'::jsonb, 'full_time', '2024-01-01', '2024-12-31', '{"en":"Hidden until published from admin.","id":"Tersembunyi sampai dipublikasikan dari admin."}'::jsonb, '{"en":"","id":""}'::jsonb, '{"en":"","id":""}'::jsonb, 'draft', null, null);
