insert into public.projects (id, slug, title, summary, thumbnail_path, type_id, category_id, project_status, started_at, ended_at, is_featured, repo_url, demo_url, play_store_url, app_store_url, overview, problem, solution, features, challenges, status, sort_order, deleted_at) values
  ('3a824cdc-8fa0-45c7-a085-fac586240033', 'pokeatlas', '{"en":"PokeAtlas","id":"PokeAtlas"}'::jsonb, '{"en":"A Pokémon encyclopedia with fast search, rich detail pages, and offline favorites.","id":"Ensiklopedia Pokémon dengan pencarian cepat, halaman detail lengkap, dan favorit offline."}'::jsonb, null, '530deb79-b358-4a80-ae9e-ec1881b1762c', '5ed93fea-5b38-4aa1-a92c-6353a78bd9e1', 'in_progress', '2026-09-01', null, true, null, null, null, null, '{"en":"**PokeAtlas** is a fast, offline-friendly Pokédex built with Flutter. It pulls data from the public PokeAPI and turns it into a smooth browsing experience on any phone.","id":"**PokeAtlas** adalah Pokédex yang cepat dan ramah offline, dibangun dengan Flutter. Data diambil dari PokeAPI publik lalu disajikan dengan pengalaman menjelajah yang mulus di ponsel apa pun."}'::jsonb, '{"en":"Most Pokédex apps are slow on low-end phones, need a connection for every screen, and bury useful stats under ads.","id":"Kebanyakan aplikasi Pokédex lambat di ponsel kelas bawah, butuh koneksi di setiap layar, dan menyembunyikan statistik penting di balik iklan."}'::jsonb, '{"en":"A lightweight app with aggressive caching, paginated lists, and a clean detail screen.\n\n- Responses are cached locally, so visited Pokémon load instantly offline.\n- Images are resized and cached to keep scrolling at 60 fps.","id":"Aplikasi ringan dengan caching agresif, daftar berhalaman, dan layar detail yang bersih.\n\n- Respons disimpan lokal, sehingga Pokémon yang pernah dibuka langsung tampil saat offline.\n- Gambar diperkecil dan di-cache agar scroll tetap 60 fps."}'::jsonb, '{"en":"- Instant search by name or number\n- Type, ability, and evolution details\n- Offline favorites\n- Light haptics and smooth hero animations","id":"- Pencarian instan berdasarkan nama atau nomor\n- Detail tipe, ability, dan evolusi\n- Favorit offline\n- Haptic ringan dan animasi hero yang mulus"}'::jsonb, '{"en":"Keeping memory low while showing hundreds of images was the hardest part. I learned to profile with **Flutter DevTools**, lazy-load aggressively, and structure state with GetX controllers per screen.","id":"Bagian tersulit adalah menjaga memori tetap rendah saat menampilkan ratusan gambar. Saya belajar profiling dengan **Flutter DevTools**, lazy-load secara agresif, dan menyusun state dengan controller GetX per layar."}'::jsonb, 'published', 1, null),
  ('6b0dab44-1997-4973-a8fa-285152578a0b', 'laundry-hub', '{"en":"Laundry Hub","id":"Laundry Hub"}'::jsonb, '{"en":"Order tracking app for a local laundry, with real-time status and push notifications.","id":"Aplikasi pelacakan pesanan untuk laundry lokal, dengan status real-time dan notifikasi."}'::jsonb, null, '530deb79-b358-4a80-ae9e-ec1881b1762c', 'a5f87af3-8bff-4194-aeb8-342d798129a5', 'completed', '2025-11-01', '2026-03-01', true, null, null, null, null, '{"en":"A customer app for a local laundry: place orders, track progress in real time, and get notified when clothes are ready.","id":"Aplikasi pelanggan untuk laundry lokal: buat pesanan, lacak progres secara real-time, dan dapat notifikasi saat cucian siap."}'::jsonb, '{"en":"Customers kept calling the shop to ask whether their laundry was done.","id":"Pelanggan terus menelepon toko untuk menanyakan apakah cucian sudah selesai."}'::jsonb, '{"en":"Firestore streams order status to the app, and Cloud Messaging sends a push notification at each step.","id":"Firestore mengalirkan status pesanan ke aplikasi, dan Cloud Messaging mengirim notifikasi di setiap tahap."}'::jsonb, '{"en":"- Order history\n- Live status timeline\n- Push notifications","id":"- Riwayat pesanan\n- Timeline status langsung\n- Push notification"}'::jsonb, '{"en":"","id":""}'::jsonb, 'published', null, null),
  ('f8a5a269-0459-441d-a452-be49167a6117', 'stockwise', '{"en":"StockWise","id":"StockWise"}'::jsonb, '{"en":"Inventory dashboard with stock alerts, sales charts, and role-based access.","id":"Dashboard inventaris dengan peringatan stok, grafik penjualan, dan akses berbasis peran."}'::jsonb, null, 'a73d2241-ce2f-4fb8-a9a1-b98b87d8fa81', '1ffaba94-1921-4358-adc8-5be00cab1949', 'completed', '2025-03-01', '2025-08-01', true, null, null, null, null, '{"en":"An inventory dashboard for a small warehouse, replacing spreadsheets with real-time stock and sales data.","id":"Dashboard inventaris untuk gudang kecil, menggantikan spreadsheet dengan data stok dan penjualan real-time."}'::jsonb, '{"en":"","id":""}'::jsonb, '{"en":"","id":""}'::jsonb, '{"en":"- Low-stock alerts\n- Sales charts\n- Role-based access","id":"- Peringatan stok menipis\n- Grafik penjualan\n- Akses berbasis peran"}'::jsonb, '{"en":"","id":""}'::jsonb, 'published', null, null),
  ('933ce1d3-75f6-4099-a4fc-d2ca42b92763', 'foodshare', '{"en":"FoodShare","id":"FoodShare"}'::jsonb, '{"en":"Hackathon-winning app that connects local food banks with nearby donors.","id":"Aplikasi juara hackathon yang menghubungkan bank makanan lokal dengan donatur terdekat."}'::jsonb, null, '530deb79-b358-4a80-ae9e-ec1881b1762c', 'a9709196-8bff-4537-aa61-a764a9687865', 'completed', '2025-11-18', '2025-11-20', false, null, null, null, null, '{"en":"Built in 36 hours at a campus hackathon with a team of three, and awarded **1st place**.","id":"Dibangun dalam 36 jam di hackathon kampus bersama tim tiga orang, dan meraih **juara 1**."}'::jsonb, '{"en":"","id":""}'::jsonb, '{"en":"","id":""}'::jsonb, '{"en":"- Map of nearby food banks\n- One-tap donation pickup requests","id":"- Peta bank makanan terdekat\n- Permintaan penjemputan donasi sekali ketuk"}'::jsonb, '{"en":"","id":""}'::jsonb, 'published', null, null),
  ('19db8df9-8722-4822-ab23-62f7c4cdbd65', 'portfolio', '{"en":"Portfolio Website","id":"Website Portofolio"}'::jsonb, '{"en":"This site: a bilingual portfolio with an admin CMS.","id":"Situs ini: portofolio dua bahasa dengan CMS admin."}'::jsonb, null, 'a73d2241-ce2f-4fb8-a9a1-b98b87d8fa81', '5ed93fea-5b38-4aa1-a92c-6353a78bd9e1', 'in_progress', '2026-11-01', null, false, 'https://github.com/DoniiAdityaa/portofolio-doni', null, null, null, '{"en":"This website: a bilingual portfolio with a private admin area, built with Next.js and Supabase.","id":"Website ini: portofolio dua bahasa dengan area admin privat, dibangun dengan Next.js dan Supabase."}'::jsonb, '{"en":"","id":""}'::jsonb, '{"en":"","id":""}'::jsonb, '{"en":"","id":""}'::jsonb, '{"en":"","id":""}'::jsonb, 'published', null, null);
